arguments.file_text:
@page "/chat"
@using sv_280d60a230954da9899f93b3e5276135.Components.Pages.Chat
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout @(isThreadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea ChannelName="@selectedChannelName"
                 ChannelDescription="@selectedChannelDescription"
                 Messages="messages"
                 ThreadReplyCounts="threadReplyCounts"
                 IsLoadingMore="isLoadingMore"
                 OnLoadMore="LoadOlderMessages"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage" />

    @if (isThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<Message> threadReplies = [];
    private Dictionary<int, int> threadReplyCounts = [];
    private Message? threadRootMessage;

    private int selectedChannelId;
    private string selectedChannelName = "";
    private string selectedChannelDescription = "";
    private bool isThreadOpen;
    private bool isLoadingMore;

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        selectedChannelId = channel.Id;
        selectedChannelName = channel.Name;
        selectedChannelDescription = channel.Description;

        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);
        await UpdateThreadReplyCounts();
    }

    private async Task LoadOlderMessages()
    {
        if (isLoadingMore) return;
        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannelId, messages.Count, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            await UpdateThreadReplyCounts();
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        var msg = await ChatService.SendMessageAsync(selectedChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(Message message)
    {
        threadRootMessage = message;
        threadReplies = await ChatService.GetThreadAsync(message.Id);
        isThreadOpen = true;
    }

    private void CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);

        // Update reply count in the main view
        threadReplyCounts[threadRootMessage.Id] = threadReplies.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to reflect the new reaction
        messages = await ChatService.GetMessagesAsync(selectedChannelId, 0, messages.Count);
    }

    private async Task UpdateThreadReplyCounts()
    {
        threadReplyCounts = [];
        foreach (var msg in messages.Where(m => m.ReplyToId is null))
        {
            var thread = await ChatService.GetThreadAsync(msg.Id);
            if (thread.Count > 0)
            {
                threadReplyCounts[msg.Id] = thread.Count;
            }
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d21;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #333;
    overflow-y: auto;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    color: #fff;
    border-bottom: 1px solid #333;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
}

::deep .channel-item {
    padding: 10px 16px;
    cursor: pointer;
    border-left: 3px solid transparent;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #27292d;
}

::deep .channel-item.active {
    background: #1164a3;
    border-left-color: #fff;
    color: #fff;
}

::deep .channel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.9rem;
}

::deep .channel-description {
    font-size: 0.75rem;
    color: #999;
